from .gateway import TemporaryError


def process(job_id, amount, gateway, attempts=3):
    # A receipt may already have been committed for this job (a later call,
    # or an earlier issue() that wrote before failing). Return it; never re-issue.
    committed = gateway.find(job_id)
    if committed is not None:
        return committed

    for _ in range(attempts):
        try:
            return gateway.issue(job_id, amount)
        except TemporaryError:
            # A failure can happen immediately after the write, which commits the
            # receipt even though issue() raised. Detect that and return it rather
            # than retrying (which would create a duplicate) or giving up.
            committed = gateway.find(job_id)
            if committed is not None:
                return committed
            # Otherwise the failure was before the write; safe to retry.

    # Only raise if genuinely nothing was committed across all allowed calls.
    committed = gateway.find(job_id)
    if committed is not None:
        return committed
    raise TemporaryError('exhausted')
